<script lang="ts">
 import {interfaceLanguage} from '$lib/i18n/context.svelte';const ui=interfaceLanguage();
 import {resolveEnvironment,environments,changeMapEnvironment,changeWallDefault,type WorldScene,type PixelArtPack,type WallMaterial} from '@isometrico/world';
 import {mapFloorChoices,mapFloorValue} from '$lib/workshop/resources';
 import {mapTileColor} from '$lib/workshop/map-tile-color';
 import SpriteThumbnail from './SpriteThumbnail.svelte';
 let {value,graphics,onchange}:{value:WorldScene;graphics:PixelArtPack;onchange:(value:WorldScene)=>void}=$props();
 const appearance=$derived(resolveEnvironment(value)),tiles=$derived(mapFloorChoices(graphics)),selected=$derived(mapFloorValue(graphics,value.baseTile??appearance.tile,value.baseTerrain)),tile=$derived(tiles.find(t=>t.value===selected));
 let sampled=$state<number|undefined>(),sampling=$state(false),sampleFailed=$state(false);
 $effect(()=>{const id=value.baseTile,url=id?graphics.tiles[id]:undefined,frame=id?graphics.tileFrames?.[id]:undefined;sampled=undefined;sampleFailed=false;if(!url){sampling=false;return;}let active=true;sampling=true;
  void mapTileColor(url,frame).then(color=>{if(active)sampled=color;}).catch(()=>{if(active)sampleFailed=true;}).finally(()=>{if(active)sampling=false;});return()=>{active=false;};
 });
 const automaticColor=$derived(value.baseTile?sampled??environments[value.theme].ground.top:environments[value.theme].ground.top);
 const color=$derived(value.cutColor??automaticColor),hex=$derived('#'+color.toString(16).padStart(6,'0'));
 const wallTypes=[{id:'white',label:'Blanca'},{id:'glass',label:'Cristal'},{id:'stone',label:'Piedra'},{id:'cobble',label:'Adoquín'}] as const;
</script>
<section class="appearance" aria-label={ui.text("Entorno y suelo del mapa")}>
 <label>{ui.text("Entorno")}<select aria-label={ui.text("Entorno del mapa")} value={appearance.outdoor?'exterior':'interior'} onchange={e=>onchange(changeMapEnvironment(value,e.currentTarget.value as 'interior'|'exterior'))}><option value="interior">{ui.text("Interior")}</option><option value="exterior">{ui.text("Exterior")}</option></select></label>
 {#if !appearance.outdoor}<label>{ui.text("Tipo de paredes")}<select aria-label={ui.text("Tipo de paredes")} value={appearance.wall} onchange={e=>onchange(changeWallDefault(value,e.currentTarget.value as WallMaterial))}>{#each wallTypes as wall}<option value={wall.id}>{ui.text(wall.label)}</option>{/each}</select></label><small>{ui.text("Se aplica a las paredes automáticas. Los acabados personalizados se conservan.")}</small>{/if}
 <label>{ui.text("Suelo base")}<select aria-label={ui.text("Suelo base del mapa")} value={selected} onchange={e=>{const choice=tiles.find(t=>t.value===e.currentTarget.value);if(choice)onchange({...value,baseTile:choice.id,baseTerrain:choice.familyId});}}>{#each tiles as item}<option value={item.value}>{item.label}</option>{/each}</select></label>
 {#if tile?.familyId}<div><label class="automatic"><input type="checkbox" aria-label={ui.text("Variaciones y bordes")} checked={value.baseTerrain===tile.familyId} onchange={e=>tile&&onchange({...value,baseTile:tile.id,baseTerrain:e.currentTarget.checked?tile.familyId:undefined})}/>{ui.text("Variaciones y bordes")}</label></div>{/if}
 {#if tile}<div class="tile-preview"><span class="thumb"><SpriteThumbnail image={graphics.tiles[tile.id]} frame={graphics.tileFrames?.[tile.id]} width={64} height={32}/></span><small>{tile.label}</small></div>{/if}
 <div class="cut"><span>{ui.text("Color del corte")}</span><label class="automatic"><input type="checkbox" aria-label={ui.text("Color de corte automático")} checked={value.cutColor===undefined} onchange={e=>onchange({...value,cutColor:e.currentTarget.checked?undefined:automaticColor})}/>{ui.text("Automático según el suelo")}</label><div class="cut-color" aria-busy={sampling}><span class="swatch" style:background={hex}></span>{#if value.cutColor!==undefined}<input type="color" aria-label={ui.text("Color del corte")} value={hex} onchange={e=>onchange({...value,cutColor:parseInt(e.currentTarget.value.slice(1),16)})}/>{/if}<output>{hex.toUpperCase()}</output>{#if sampling}<small>{ui.text("Calculando…")}</small>{/if}</div>{#if sampleFailed}<small role="status">{ui.text("No se pudo leer el color del tile. Puedes ajustar el corte manualmente.")}</small>{/if}</div>
 <small>{ui.text("Las baldosas pintadas y las paredes personalizadas se conservan.")}</small>
</section>
<style>
 .appearance{display:grid;gap:10px;margin:16px 0;color:#3c5135}.appearance>label{display:grid;gap:6px;font-size:12px;color:#718269;margin:0}select{width:100%;box-sizing:border-box;padding:9px;font:inherit;font-size:13px;color:#3c5135;border:1px solid #dce5d6;border-radius:6px;background:white}.appearance small{font-size:11px;line-height:1.5;color:#718269}.tile-preview{display:flex;align-items:center;gap:10px}.thumb{display:block;flex:none;width:64px;height:32px;background:#edf2e5;border-radius:5px;overflow:hidden}.cut{display:grid;gap:8px;padding:12px 0;border-top:1px solid #e2e8dd}.cut>span{font-size:12px;color:#718269}.automatic{display:flex;align-items:center;gap:7px;margin:0;font-size:11px;color:#607359}.automatic input{width:15px;height:15px;margin:0;flex:none}.cut-color{display:flex;align-items:center;gap:8px;min-height:28px}.swatch{width:28px;height:24px;flex:none;border:1px solid #cbd6c4;border-radius:5px}.cut-color input{width:34px;height:28px;box-sizing:border-box;padding:1px;background:white;border:1px solid #dce5d6;border-radius:5px}.cut-color output{font-family:monospace;font-size:11px;color:#52664a}select:focus-visible,input:focus-visible{outline:2px solid #74994e;outline-offset:2px}
</style>
